'use strict';
const previewFrameCache=new Map(),previewCacheLimit=64*1024*1024;
let previewCacheBytes=0,previewCacheEpoch=0,preparingPreview=false,cancelPreviewPreparation=false,previewOriginalSize=null,previewCacheHits=0;
const previewTools=document.createElement('details');previewTools.id='previewTools';previewTools.className='preview-tools';previewTools.innerHTML='<summary>Preview quality</summary><div><label>Quality<select id="previewQuality"><option value="draft">Draft · faster</option><option value="balanced" selected>Balanced</option><option value="high">High detail</option></select></label><button id="preparePreviewCache">Cache from playhead</button><button id="clearPreviewCache">Clear cache</button><button id="cancelPreviewCache" hidden>Cancel</button><p id="previewCacheStatus" class="note" role="status">Playback cache uses up to 64 MB. Export always uses your export settings.</p></div>';
$('previewPlaybackSpeed').closest('label').after(previewTools);
try{const quality=localStorage.getItem('elleson-preview-quality');if(['draft','balanced','high'].includes(quality))$('previewQuality').value=quality}catch{}
function previewPixelSize(){const width={draft:480,balanced:960,high:1440}[$('previewQuality').value]||960;return{width,height:width*9/16}}
function clearPlaybackCache(){for(const frame of previewFrameCache.values()){frame.canvas.width=frame.canvas.height=0}previewFrameCache.clear();previewCacheBytes=0;previewCacheEpoch++;updatePreviewCacheStatus()}
function previewCacheKey(t=time){return previewCacheEpoch+':'+sceneIndex+':'+Math.floor((t+1e-7)*30)}
function cachePreviewFrame(key){const source=$('stage'),bytes=source.width*source.height*4;if(bytes>previewCacheLimit)return;while(previewCacheBytes+bytes>previewCacheLimit&&previewFrameCache.size){const oldest=previewFrameCache.keys().next().value,entry=previewFrameCache.get(oldest);previewCacheBytes-=entry.bytes;entry.canvas.width=entry.canvas.height=0;previewFrameCache.delete(oldest)}const canvas=document.createElement('canvas');canvas.width=source.width;canvas.height=source.height;canvas.getContext('2d').drawImage(source,0,0);const previous=previewFrameCache.get(key);if(previous){previewCacheBytes-=previous.bytes;previous.canvas.width=previous.canvas.height=0}previewFrameCache.set(key,{canvas,bytes});previewCacheBytes+=bytes}
function updatePreviewCacheStatus(message=null){if(!$('previewCacheStatus'))return;$('previewCacheStatus').textContent=message||(previewFrameCache.size+' frames cached · '+(previewCacheBytes/1048576).toFixed(1)+' / 64 MB · export quality unchanged')}
function previewAssetSources(s){if(!s)return[];return[s.backgroundImage,...s.objects.flatMap(o=>{const art=[o,...Object.values(o.characterViews||{})];return[o.src,...art.flatMap(v=>[...v.parts?.map(p=>p.src)||[],...Object.values(v.mouth?.sprites||{}),...(v.type==='puppet'||v.parts?puppetFaceSources(v):[])]),...o.frames?.map(f=>f.src)||[],...Object.values(o.handSprites||{}).flatMap(view=>Object.values(view).flatMap(side=>Object.values(side).map(p=>p.src)))]})].filter(src=>typeof src==='string'&&src.startsWith('data:image/'))}
function previewHasVideo(){return current().objects.some(o=>o.type==='video')||project.scenes[sceneIndex+1]?.objects.some(o=>o.type==='video')}
function canCachePreviewScene(){return !previewHasVideo()&&[...previewAssetSources(current()),...previewAssetSources(project.scenes[sceneIndex+1])].every(src=>!src.startsWith('data:image/gif')&&images.get(src)?.complete&&images.get(src)?.naturalWidth)}
function setPlaybackPixels(){if(!previewOriginalSize)previewOriginalSize={width:$('stage').width,height:$('stage').height};const size=previewPixelSize();if($('stage').width!==size.width||$('stage').height!==size.height){$('stage').width=size.width;$('stage').height=size.height}}
function restorePlaybackPixels(){if(!previewOriginalSize)return;$('stage').width=previewOriginalSize.width;$('stage').height=previewOriginalSize.height;previewOriginalSize=null}
const drawBeforePlaybackCache=draw;draw=function(){if(recording||preparingPreview)return drawBeforePlaybackCache();if(!playing){restorePlaybackPixels();return drawBeforePlaybackCache()}setPlaybackPixels();const key=previewCacheKey(),cached=canCachePreviewScene()&&previewFrameCache.get(key);if(cached){previewFrameCache.delete(key);previewFrameCache.set(key,cached);ctx.save();ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,$('stage').width,$('stage').height);ctx.drawImage(cached.canvas,0,0,$('stage').width,$('stage').height);ctx.restore();previewCacheHits++;$('clock').innerHTML=time.toFixed(2)+' <small>/ '+current().duration.toFixed(2)+' s</small>';$('scrub').value=time;updatePlayhead();if(typeof positionSelectionToolbar==='function')positionSelectionToolbar()}else{drawBeforePlaybackCache();if(canCachePreviewScene())cachePreviewFrame(key)}updatePreviewCacheStatus()};
const stopBeforePlaybackCache=stop;stop=function(){const resized=!!previewOriginalSize;stopBeforePlaybackCache();if(!preparingPreview){restorePlaybackPixels();if(resized&&!recording)drawBeforePlaybackCache()}};
const saveBeforePlaybackCache=save;save=function(){clearPlaybackCache();return saveBeforePlaybackCache()};
const loadBeforePlaybackCache=loadProject;loadProject=function(...args){clearPlaybackCache();return loadBeforePlaybackCache(...args)};
const historyBeforePlaybackCache=restoreHistory;restoreHistory=function(...args){clearPlaybackCache();return historyBeforePlaybackCache(...args)};
$('previewQuality').onchange=()=>{const resume=playing;stop();clearPlaybackCache();try{localStorage.setItem('elleson-preview-quality',$('previewQuality').value)}catch{}if(resume)play();else draw()};$('clearPreviewCache').onclick=clearPlaybackCache;$('cancelPreviewCache').onclick=()=>cancelPreviewPreparation=true;
async function preparePlaybackCache(){if(recording||playing||preparingPreview||window.editorTaskBusy||audioBusy)throw Error('Stop playback and finish media tasks before caching.');if(previewHasVideo()||[...previewAssetSources(current()),...previewAssetSources(project.scenes[sceneIndex+1])].some(src=>src.startsWith('data:image/gif')))throw Error('This scene includes video or an animated image. Choose Draft quality for faster previews.');stop();const old={time,sceneIndex,selected,selectedAudio,width:$('stage').width,height:$('stage').height},epoch=previewCacheEpoch,owner=project,size=previewPixelSize(),frames=Math.min(Math.ceil((current().duration-time)*30),Math.floor(previewCacheLimit/(size.width*size.height*4))),start=Math.floor(time*30);await Promise.all([...new Set([...previewAssetSources(current()),...previewAssetSources(project.scenes[sceneIndex+1])])].map(async src=>{const image=await imageReady(src);images.set(src,image)}));await preloadProductionAssets(current());if(project!==owner||sceneIndex!==old.sceneIndex)throw Error('The scene changed during preparation.');const frozen=[...document.querySelectorAll('button,input,select,textarea')].filter(e=>e.id!=='cancelPreviewCache').map(e=>[e,e.disabled]);frozen.forEach(([e])=>e.disabled=true);preparingPreview=true;cancelPreviewPreparation=false;window.editorTaskBusy=true;recording=true;$('cancelPreviewCache').hidden=false;$('stage').width=size.width;$('stage').height=size.height;let completed=0;try{for(let i=0;i<frames;i++){if(cancelPreviewPreparation||project!==owner||epoch!==previewCacheEpoch)break;time=(start+i)/30;drawBeforePlaybackCache();cachePreviewFrame(previewCacheKey(time));completed++;if(i%4===0){updatePreviewCacheStatus('Caching '+(i+1)+' / '+frames+' frames…');await new Promise(ok=>setTimeout(ok,0))}}}finally{recording=false;preparingPreview=false;window.editorTaskBusy=false;$('cancelPreviewCache').hidden=true;Object.assign($('stage'),{width:old.width,height:old.height});sceneIndex=old.sceneIndex;time=old.time;selected=old.selected;selectedAudio=old.selectedAudio;frozen.forEach(([e,disabled])=>e.disabled=disabled);render();updatePreviewCacheStatus((cancelPreviewPreparation?'Stopped. ':'')+completed+' frames cached from playhead · '+(completed/30).toFixed(1)+'s · '+(previewCacheBytes/1048576).toFixed(1)+' MB')}return completed}
$('preparePreviewCache').onclick=()=>preparePlaybackCache().catch(e=>updatePreviewCacheStatus(e.message));
